func (r *AppscopeConfigResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	dec := json.NewDecoder(bytes.NewReader([]byte(req.ID)))
	dec.DisallowUnknownFields()
	var data struct {
		GroupID string `json:"group_id"`
		ID      string `json:"id"`
	}
	if err := dec.Decode(&data); err != nil {
		resp.Diagnostics.AddError("Invalid ID", `The import ID is not valid. It is expected to be a JSON object string with the required path parameters: `+err.Error())
		return
	}
	if data.GroupID == "" {
		resp.Diagnostics.AddError("Missing required field", `The field group_id is required but was not found in the json encoded ID.`)
		return
	}
	if data.ID == "" {
		resp.Diagnostics.AddError("Missing required field", `The field id is required but was not found in the json encoded ID.`)
		return
	}
	var model AppscopeConfigModel
	model.GroupID = types.StringValue(data.GroupID)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("group_id"), data.GroupID)...)
	model.ID = types.StringValue(data.ID)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("id"), data.ID)...)
	if resp.Diagnostics.HasError() {
		return
	}
	apiModel, err := r.api.Read(ctx, model)
	if err != nil {
		resp.Diagnostics.AddError("failure to invoke API", err.Error())
		return
	}
	applyAppscopeConfigAPIToState(apiModel, &model, true, true)
	resp.Diagnostics.Append(resp.State.Set(ctx, &model)...)
}

func isAppscopeConfigImportState(state *AppscopeConfigModel) bool {
	if state == nil {
		return false
	}
	if state.Config.IsNull() || state.Config.IsUnknown() {
		return true
	}
	if state.Description.IsNull() || state.Description.IsUnknown() {
		return true
	}
	if state.Lib.IsNull() || state.Lib.IsUnknown() {
		return true
	}
	return false
}

func applyAppscopeConfigAPIToState(api *AppscopeConfigModel, state *AppscopeConfigModel, preserveInputs bool, fillMissingInputs bool) {
	if api == nil || state == nil {
		return
	}
	if !preserveInputs || (fillMissingInputs && (state.Config.IsNull() || state.Config.IsUnknown())) {
		if !api.Config.IsNull() && !api.Config.IsUnknown() {
			state.Config = api.Config
		}
	}
	if len(state.Config.AttributeTypes(context.Background())) == 0 {
		state.Config = types.ObjectNull(AppscopeConfigConfigAttrTypes())
	}
	if !preserveInputs || (fillMissingInputs && (state.Description.IsNull() || state.Description.IsUnknown())) {
		if !api.Description.IsNull() && !api.Description.IsUnknown() {
			state.Description = api.Description
		}
	}
	if !preserveInputs || (fillMissingInputs && (state.GroupID.IsNull() || state.GroupID.IsUnknown())) {
		if !api.GroupID.IsNull() && !api.GroupID.IsUnknown() {
			state.GroupID = api.GroupID
		}
	}
	if !preserveInputs || (fillMissingInputs && (state.ID.IsNull() || state.ID.IsUnknown())) {
		if !api.ID.IsNull() && !api.ID.IsUnknown() {
			state.ID = api.ID
		}
	}
	if !preserveInputs || (fillMissingInputs && (state.Lib.IsNull() || state.Lib.IsUnknown())) {
		if !api.Lib.IsNull() && !api.Lib.IsUnknown() {
			state.Lib = api.Lib
		}
	}
	if !preserveInputs || (fillMissingInputs && (state.Tags.IsNull() || state.Tags.IsUnknown())) {
		if !api.Tags.IsNull() && !api.Tags.IsUnknown() {
			state.Tags = api.Tags
		}
	}
}

